// timeout: 120
// dyna:dataframe against answers computed OUTSIDE this engine
// (tests/corpus/ref/dataframe_vectors.js, generated by
// tools/gen_dataframe_ref_vectors.py: exact rational arithmetic for the
// moments, numpy/pandas/scipy for order statistics, scans and groupby, each
// mapped to the convention dynajs.d.ts states for the verb).
//
// The datasets are rebuilt here from the same splitmix64 stream the
// generator used, with + - * and floor only, so they are bit-identical to
// the ones the answers were computed from; makeData() and make() in the
// generator must stay in lockstep.
//
// A float answer is held to a bar in ULPs of a SCALE that the verb states:
// the answer itself where the answer is well conditioned (means, moments,
// order statistics), the data's magnitude where the verb is a sum of
// signed terms whose total can be far smaller than its parts (sums, diffs,
// rolling sums), so a correct summation that loses digits to cancellation
// is not called wrong and a wrong one is.
//
//   ./dynajs tests/dataframe/test_dataframe_ref.js            assert
//   ./dynajs tests/dataframe/test_dataframe_ref.js --report   print each verb's worst row
import { DataFrame } from "dyna:dataframe";
import { ROWS } from "../corpus/ref/dataframe_vectors.js";

const report = typeof scriptArgs !== "undefined" && scriptArgs.includes("--report");
let n = 0, fails = 0;
function fail(m) { fails++; print("FAIL: " + m); }

// ---- the shared generator -------------------------------------------------
const M64 = (1n << 64n) - 1n;
function splitmix(seed) {
    let s = BigInt(seed) & M64;
    return () => {
        s = (s + 0x9E3779B97F4A7C15n) & M64;
        let z = s;
        z = ((z ^ (z >> 30n)) * 0xBF58476D1CE4E5B9n) & M64;
        z = ((z ^ (z >> 27n)) * 0x94D049BB133111EBn) & M64;
        z = z ^ (z >> 31n);
        return Number(z >> 11n) * (1 / 9007199254740992);
    };
}
function makeData(kind, size, seed) {
    const u = splitmix(seed);
    const x = new Float64Array(size), y = new Float64Array(size), w = new Float64Array(size), k = new Int32Array(size);
    for (let i = 0; i < size; i++) {
        let v;
        if (kind === "uniform") v = u() * 200.0 - 100.0;
        else if (kind === "normalish") { v = 0.0; for (let j = 0; j < 12; j++) v += u(); v -= 6.0; }
        else if (kind === "offset") v = 1e9 + (u() - 0.5);
        else if (kind === "ties") v = Math.floor(u() * 7.0);
        else if (kind === "near1") v = 1.0 + (u() - 0.5) * 0.02;
        else throw new Error("unknown dataset kind " + kind);
        x[i] = v;
        y[i] = 0.5 * v + (u() - 0.5) * 10.0;
        w[i] = u();
        k[i] = Math.floor(u() * 13.0);
    }
    return { x, y, w, k };
}
const frames = new Map();
function frameFor(ds) {
    let f = frames.get(ds);
    if (!f) {
        const [kind, size, seed] = ds.split(":");
        const d = makeData(kind, +size, +seed);
        f = { df: new DataFrame(d), data: d };
        frames.set(ds, f);
    }
    return f;
}

// ---- error measure --------------------------------------------------------
const F64 = new Float64Array(1), U64 = new BigUint64Array(F64.buffer);
function ulp(x) {
    x = Math.abs(x);
    if (!isFinite(x)) return NaN;
    if (x < 2.2250738585072014e-308) return 5e-324;
    F64[0] = x; U64[0] += 1n;
    return F64[0] - x;
}
function err(got, want, scale) {
    if (typeof want !== "number") return Object.is(got, want) ? 0 : Infinity;
    if (Number.isNaN(want)) return Number.isNaN(got) ? 0 : Infinity;
    if (!isFinite(want)) return got === want ? 0 : Infinity;
    if (typeof got !== "number" || !isFinite(got)) return Infinity;
    if (got === want) return 0;
    return Math.abs(got - want) / ulp(Math.max(Math.abs(want), scale || 0));
}
const absMax = (a) => { let m = 0; for (const v of a) if (Math.abs(v) > m) m = Math.abs(v); return m; };
const absSum = (a) => { let s = 0; for (const v of a) s += Math.abs(v); return s; };

// verb -> [bar in ULPs, scale(data, args) or undefined (the answer itself)]
const VALUE = (bar) => [bar, undefined];
const DATA = (bar) => [bar, (d) => absMax(d.x)];
const SUMS = (bar) => [bar, (d) => absSum(d.x)];
const SPEC = {
    SUM: SUMS(4), MEAN: SUMS(4), DOT_PRODUCT: [4, (d) => { let s = 0; for (let i = 0; i < d.x.length; i++) s += Math.abs(d.x[i] * d.y[i]); return s; }],
    VARIANCE: VALUE(16), STDDEV: VALUE(16), VARIANCE_POP: VALUE(16), STDDEV_POP: VALUE(16), SEM: VALUE(16),
    // excess kurtosis is m4/m2^2 - 3: the subtraction is the conditioning,
    // so it is measured against |k| + 3, the size of the ratio it came from
    SKEW: VALUE(64), KURTOSIS: [64, (d, a, w) => Math.abs(w) + 3], SKEW_SAMP: VALUE(64), KURT_SAMP: [64, (d, a, w) => Math.abs(w) + 3],
    MAD: VALUE(32), MEDIAN_ABSOLUTE_DEVIATION: VALUE(0), MEDIAN: VALUE(0),
    MIN: VALUE(0), MAX: VALUE(0), ARG_MIN: VALUE(0), ARG_MAX: VALUE(0),
    QUANTILE: DATA(2), PERCENTILE_CONT: DATA(2), QUANTILES: DATA(2),
    QUANTILE_EXACT_LOW: VALUE(0), QUANTILE_EXACT_HIGH: VALUE(0), PERCENTILE_DISC: VALUE(0),
    COV_POP: VALUE(16), COV_SAMP: VALUE(16), CORR: VALUE(16), REGR_SLOPE: VALUE(16),
    // the intercept is mean(y) - slope * mean(x): measured against the terms
    REGR_INTERCEPT: [64, (d) => { const n = d.x.length; let sx = 0, sy = 0; for (let i = 0; i < n; i++) { sx += d.x[i]; sy += d.y[i]; } return Math.abs(sy / n) + Math.abs(sx / n); }],
    REGR_R2: VALUE(32), REGR_SXX: VALUE(32), REGR_SYY: VALUE(32), REGR_SXY: VALUE(32),
    REGR_AVG_X: SUMS(4), REGR_AVG_Y: [4, (d) => absSum(d.y)], MEAN_WEIGHTED: VALUE(16), DELTA_SUM: VALUE(16),
    RANK_CORR: VALUE(16), PRODUCT: VALUE(64),
    ENTROPY: VALUE(8), N_UNIQUE: VALUE(0), MODE: VALUE(0),
    CUM_SUM: SUMS(4), CUM_MAX: VALUE(0), CUM_MIN: VALUE(0), SHIFT: VALUE(0), DIFF: DATA(1),
    ROLLING_SUM: SUMS(4), ROLLING_MEAN: DATA(4), ROLLING_MIN: VALUE(0), ROLLING_MAX: VALUE(0),
    ROLLING_VAR: VALUE(16), ROLLING_STD: VALUE(16),
    EMA: DATA(8), PCT_CHANGE: VALUE(2), ZSCORE: DATA(16),
    RANK: VALUE(0), DENSE_RANK: VALUE(0), PERCENT_RANK: VALUE(1), SORT: VALUE(0), N_LARGEST: VALUE(0), N_SMALLEST: VALUE(0),
};

const worst = new Map();
function note(verb, e, bar, at) {
    const r = e / Math.max(bar, 0.5);
    const w = worst.get(verb);
    if (!w || r > w[0]) worst.set(verb, [r, at]);
    if (!report && !(e <= bar)) fail(at);
}
const label = (ds, verb, args) => verb + "(" + JSON.stringify(args).slice(1, -1) + ") on " + ds;
function cmpMap(ds, verb, args, gotKeys, gotVals, want, bar) {
    n++;
    const got = new Map();
    for (let i = 0; i < gotKeys.length; i++) got.set(Number(gotKeys[i]), gotVals[i]);
    const wk = Object.keys(want);
    if (got.size !== wk.length) { fail(label(ds, verb, args) + ": " + got.size + " groups, want " + wk.length); return; }
    for (const key of wk) {
        const g = got.get(Number(key));
        const e = err(g, want[key], 0);
        note(verb, e, bar, label(ds, verb, args) + " group " + key + ": " + g + ", want " + want[key] + " (" + e.toFixed(1) + " ulp)");
    }
}

for (const [ds, verb, args, want] of ROWS) {
    const { df, data } = frameFor(ds);
    let got;
    try { got = df[verb](...args); } catch (e) { n++; fail(label(ds, verb, args) + " threw " + e.message); continue; }
    if (verb === "VALUE_COUNTS" || verb.startsWith("GROUP_BY_")) {
        cmpMap(ds, verb, args, got.keys, got.values, want, verb === "GROUP_BY_MEAN" ? 16 : (verb === "GROUP_BY_SUM" ? 64 : 0));
        continue;
    }
    if (verb === "UNIQUE") {
        n++;
        if (JSON.stringify(Array.from(got)) !== JSON.stringify(want)) fail(label(ds, verb, args) + ": " + JSON.stringify(Array.from(got)).slice(0, 80) + " vs " + JSON.stringify(want).slice(0, 80));
        continue;
    }
    if (verb === "HISTOGRAM") {
        n++;
        const ce = JSON.stringify(Array.from(got.counts)) === JSON.stringify(want.counts);
        if (!ce) fail(label(ds, verb, args) + ": counts " + Array.from(got.counts) + " vs " + want.counts);
        const ee = Math.max(...want.edges.map((v, i) => err(got.edges[i], v, absMax(data.x))));
        note(verb, ee, 4, label(ds, verb, args) + ": edges off by " + ee.toFixed(1) + " ulp");
        continue;
    }
    const spec = SPEC[verb];
    if (!spec) { n++; fail("no SPEC entry for " + verb + " -- the vectors test it and this suite does not say how"); continue; }
    const [bar, scaleOf] = spec;
    const scale = scaleOf ? scaleOf(data, args, Array.isArray(want) ? 0 : want) : 0;
    const wants = Array.isArray(want) ? want : [want];
    const gots = Array.isArray(want) ? Array.from(got) : [got];
    n++;
    if (gots.length !== wants.length) { fail(label(ds, verb, args) + ": " + gots.length + " values, want " + wants.length); continue; }
    let e = 0, at = -1;
    for (let i = 0; i < wants.length; i++) { const ei = err(gots[i], wants[i], scale); if (ei > e || Number.isNaN(ei)) { e = ei; at = i; } }
    note(verb, e, bar, label(ds, verb, args) + (wants.length > 1 ? " [" + at + "]" : "") + ": " + gots[Math.max(at, 0)] + ", want " + wants[Math.max(at, 0)] + " (" + (isFinite(e) ? e.toFixed(1) : e) + " ulp, bar " + bar + ")");
}

// ---- which groups a grouped verb lists -------------------------------------
// Integer keys are DENSE (the d.ts contract, pinned by
// test_dataframe_group_keys.js): every key 0..max is listed, empty ones
// included. String keys list the strings the rows hold -- a string column's
// dictionary outlives its rows (SLICE and FILTER keep it), and those leftover
// strings used to come back as groups with no rows. Groups a MASK empties are
// still listed (their mean is NaN).
{
    const verbs = [["GROUP_BY_SUM", ["k", "x"]], ["SUM_MAP", ["k", "x"]], ["GROUP_BY_MIN", ["k", "x"]], ["GROUP_BY_MAX", ["k", "x"]],
        ["GROUP_BY_MEAN", ["k", "x"]], ["GROUP_BY_COUNT", ["k"]], ["MIN_MAP", ["k", "x"]], ["MAX_MAP", ["k", "x"]],
        ["GROUP_ARRAY", ["k", "x"]], ["GROUP_UNIQ_ARRAY", ["k", "x"]], ["GROUP_ARRAY_MOVING_SUM", ["k", "x", 2]],
        ["GROUP_ARRAY_MOVING_AVG", ["k", "x", 2]], ["GROUP_ARRAY_SORTED", ["k", "x"]], ["GROUP_ARRAY_LAST", ["k", "x", 2]],
        ["GROUP_ARRAY_SAMPLE", ["k", "x", 2]], ["GROUP_BIT_AND", ["k", "i"]], ["GROUP_BIT_OR", ["k", "i"]], ["GROUP_BIT_XOR", ["k", "i"]]];
    // rows: keys 2, 11, 2, 11, 2 with x = 1..5 and i = 1, 2, 4, 8, 16
    const want = { GROUP_BY_SUM: [9, 6], SUM_MAP: [9, 6], GROUP_BY_MIN: [1, 2], GROUP_BY_MAX: [5, 4], GROUP_BY_MEAN: [3, 3],
        GROUP_BY_COUNT: [3, 2], MIN_MAP: [1, 2], MAX_MAP: [5, 4], GROUP_ARRAY: [[1, 3, 5], [2, 4]], GROUP_UNIQ_ARRAY: [[1, 3, 5], [2, 4]],
        GROUP_ARRAY_MOVING_SUM: [[1, 4, 8], [2, 6]], GROUP_ARRAY_MOVING_AVG: [[1, 2, 4], [2, 3]], GROUP_ARRAY_SORTED: [[1, 3, 5], [2, 4]],
        GROUP_ARRAY_LAST: [[3, 5], [2, 4]], GROUP_ARRAY_SAMPLE: [[1, 3], [2, 4]], GROUP_BIT_AND: [0, 0], GROUP_BIT_OR: [21, 10], GROUP_BIT_XOR: [21, 10] };
    const el = (e) => (typeof e === "object" ? Array.from(e) : e);
    const pick = (r, idx) => JSON.stringify(idx.map((i) => el(r.values[i])));
    const x = new Float64Array([1, 2, 3, 4, 5]), i = new Int32Array([1, 2, 4, 8, 16]);
    const dense = new DataFrame({ k: new Int32Array([2, 11, 2, 11, 2]), x, i });
    // the string frame: two leading rows whose strings ("p", "z") the slice drops
    const sliced = new DataFrame({ k: ["p", "z", "b", "e", "b", "e", "b"], x: new Float64Array([9, 9, 1, 2, 3, 4, 5]), i: new Int32Array([9, 9, 1, 2, 4, 8, 16]) }).SLICE(2);
    for (const [verb, args] of verbs) {
        n++;
        const r = dense[verb](...args);
        if (r.keys.length !== 12 || r.keys[0] !== 0 || r.keys[11] !== 11) fail(verb + ": integer keys {2, 11} must list 0..11 (dense), got " + JSON.stringify(r.keys));
        else if (pick(r, [2, 11]) !== JSON.stringify(want[verb])) fail(verb + " on dense keys: " + pick(r, [2, 11]) + ", want " + JSON.stringify(want[verb]));
        n++;
        const t = sliced[verb](...args);
        if (JSON.stringify(t.keys) !== '["b","e"]') fail(verb + ": a sliced string column must list only the strings its rows hold, got " + JSON.stringify(t.keys));
        else if (pick(t, [0, 1]) !== JSON.stringify(want[verb])) fail(verb + " on string keys: " + pick(t, [0, 1]) + ", want " + JSON.stringify(want[verb]));
    }
    n++;
    const m = sliced.GROUP_BY_MEAN("k", "x", new Uint8Array([1, 0, 1, 0, 1]));
    if (JSON.stringify(m.keys) !== '["b","e"]' || m.values[0] !== 3 || !Number.isNaN(m.values[1]))
        fail("a group the mask empties is still listed, with a NaN mean: " + JSON.stringify(m.keys) + " " + Array.from(m.values));
    n++;
    let coerced = 0;
    const key = { toString() { coerced++; return "k"; } };
    const r = sliced.GROUP_BY_SUM(key, "x");
    if (coerced !== 1 || JSON.stringify(r.keys) !== '["b","e"]') fail("the key argument is coerced exactly once (" + coerced + ")");
}

if (report) for (const [verb, [r, at]] of [...worst].sort((a, b) => b[1][0] - a[1][0])) print((verb + "                          ").slice(0, 26) + " worst/bar " + (isFinite(r) ? r.toFixed(2) : r) + "  " + at.slice(0, 170));
print("test_dataframe_ref: " + n + " checks, " + fails + " failures");
if (fails) throw new Error(fails + " failures");
